exercices.solution:
void tri_insertion(int t[], int n) {
    for (int i = 1; i < n; i++) {
        int cle = t[i];
        int j = i - 1;
        while (j >= 0 && t[j] > cle) {
            t[j + 1] = t[j];
            j--;
        }
        t[j + 1] = cle;
    }
}
